**Step 1** — Retrieve payment methods assigned to your vendor account.

**Endpoint:** `GET /api/v3/getTrPaymentmethods`

Present the `data` array in your app UI. Each item includes `payment_method_id`, localized names, `redirect`, and `logo`.

**Mobile (step 1):** Call this after `POST /oauth/token`. Use `payment_method_id` when calling `createTransaction`. If `redirect` is `"true"`, open the returned checkout `url` in a WebView; if `"false"`, expect a synchronous provider response from direct-dispatch.

**React Native:**
```javascript
const apiUrl = 'https://app.fawaterk.com/api/v3/getTrPaymentmethods';
const accessToken = 'YOUR_OAUTH_ACCESS_TOKEN';

fetch(apiUrl, {
  method: 'GET',
  headers: {
    'Content-Type': 'application/json',
    Authorization: `Bearer ${accessToken}`,
  },
})
  .then((r) => r.json())
  .then(console.log)
  .catch(console.error);
```

**Kotlin:**
```kotlin
val apiUrl = "https://app.fawaterk.com/api/v3/getTrPaymentmethods"
val accessToken = "YOUR_OAUTH_ACCESS_TOKEN"

val client = OkHttpClient()
val request = Request.Builder()
    .url(apiUrl)
    .addHeader("Content-Type", "application/json")
    .addHeader("Authorization", "Bearer $accessToken")
    .build()

client.newCall(request).execute().use { response ->
    if (response.isSuccessful) {
        println(response.body?.string())
    } else {
        println("Request failed: ${response.code}")
    }
}
```

**Java:**
```java
String apiUrl = "https://app.fawaterk.com/api/v3/getTrPaymentmethods";
String accessToken = "YOUR_OAUTH_ACCESS_TOKEN";

OkHttpClient client = new OkHttpClient();
Request request = new Request.Builder()
    .url(apiUrl)
    .addHeader("Content-Type", "application/json")
    .addHeader("Authorization", "Bearer " + accessToken)
    .build();

try (Response response = client.newCall(request).execute()) {
    if (response.isSuccessful() && response.body() != null) {
        System.out.println(response.body().string());
    } else {
        System.out.println("Request failed: " + response.code());
    }
}
```

**Swift:**
```swift
let apiUrl = "https://app.fawaterk.com/api/v3/getTrPaymentmethods"
let accessToken = "YOUR_OAUTH_ACCESS_TOKEN"

if let url = URL(string: apiUrl) {
    var request = URLRequest(url: url)
    request.setValue("application/json", forHTTPHeaderField: "Content-Type")
    request.setValue("Bearer \(accessToken)", forHTTPHeaderField: "Authorization")

    URLSession.shared.dataTask(with: request) { data, _, error in
        if let error = error {
            print("Error: \(error)")
            return
        }
        if let data = data, let body = String(data: data, encoding: .utf8) {
            print(body)
        }
    }.resume()
}
```

**Flutter:**
```dart
import 'dart:convert';
import 'package:http/http.dart' as http;

Future<void> fetchPaymentMethods() async {
  const apiUrl = 'https://app.fawaterk.com/api/v3/getTrPaymentmethods';
  const accessToken = 'YOUR_OAUTH_ACCESS_TOKEN';

  final response = await http.get(
    Uri.parse(apiUrl),
    headers: {
      'Content-Type': 'application/json',
      'Authorization': 'Bearer $accessToken',
    },
  );
  print(json.encode(json.decode(response.body)));
}
```

**Step 2** — Create a **TR** transaction and initiate payment on the selected method.

**Endpoint:** `POST /api/v3/createTransaction`

Include `payment_method_id` from step 1 plus cart/customer fields. Response shape depends on the method:

- **Card / redirect methods** — hosted checkout URL in `data.url` (open in WebView)
- **Fawry** — direct-dispatch reference code
- **Meeza** — wallet RTP / reference in provider response

Use `intent_key` from the response to correlate with webhooks and `POST /api/v3/getTransactionData`.

**Mobile (step 2):** Include `payment_method_id` from step 1.

| Mode | When | Mobile action |
|------|------|---------------|
| **Link** | `redirect` = `"true"` (e.g. Visa/Mastercard) | Open `data.url` in WebView |
| **Direct-dispatch** | `redirect` = `"false"` (e.g. Fawry, Meeza) | Show reference / handle RTP from provider body |

**React Native:**
```javascript
const API_URL = 'https://app.fawaterk.com/api/v3/createTransaction';
const accessToken = 'YOUR_OAUTH_ACCESS_TOKEN';
const PAYMENT_ID = 4; // from getTrPaymentmethods

fetch(API_URL, {
  method: 'POST',
  headers: {
    Authorization: `Bearer ${accessToken}`,
    'Content-Type': 'application/json',
  },
  body: JSON.stringify({
    payment_method_id: PAYMENT_ID,
    cartTotal: '100',
    currency: 'EGP',
    customer: {
      first_name: 'Ahmed',
      last_name: 'Ali',
      email: 'ahmed@example.com',
      phone: '01000000000',
      address: 'Cairo',
    },
    redirectionUrls: {
      successUrl: 'https://yoursite.com/success',
      failUrl: 'https://yoursite.com/fail',
      pendingUrl: 'https://yoursite.com/pending',
      webhookUrl: 'https://yoursite.com/webhooks/fawaterak_json',
    },
    cartItems: [{ name: 'Order total', price: '100', quantity: '1' }],
  }),
})
  .then((r) => r.json())
  .then(console.log)
  .catch(console.error);
```

**Kotlin:**
```kotlin
val apiUrl = "https://app.fawaterk.com/api/v3/createTransaction"
val accessToken = "YOUR_OAUTH_ACCESS_TOKEN"
val payment_method_id = 4

val requestData = """
{"payment_method_id":$payment_method_id,"cartTotal":"100","currency":"EGP",
"customer":{"first_name":"Ahmed","last_name":"Ali","email":"ahmed@example.com","phone":"01000000000","address":"Cairo"},
"redirectionUrls":{"successUrl":"https://yoursite.com/success","failUrl":"https://yoursite.com/fail","pendingUrl":"https://yoursite.com/pending","webhookUrl":"https://yoursite.com/webhooks/fawaterak_json"},
"cartItems":[{"name":"Order total","price":"100","quantity":"1"}]}
""".trimIndent()

val client = OkHttpClient()
val body = requestData.toRequestBody("application/json".toMediaType())
val request = Request.Builder()
    .url(apiUrl)
    .addHeader("Authorization", "Bearer $accessToken")
    .addHeader("Content-Type", "application/json")
    .post(body)
    .build()

client.newCall(request).execute().use { response ->
    println(if (response.isSuccessful) response.body?.string() else "Failed: ${response.code}")
}
```

